css:
body {
	margin: 0;
	font-family: sans-serif;
}

.page.mk-gn0ga6 {
				padding: 16px;
				background: #e9ecef;
			}
			.heading.mk-gn0ga6 {
				margin: 0 0 12px;
				font-size: 26px;
				font-weight: 700;
				color: #212529;
			}
			.grid.mk-gn0ga6 {
				display: grid;
				grid-template-columns: repeat(3, minmax(0, 1fr));
				gap: 8px;
			}
			.card.mk-gn0ga6 {
				display: grid;
				grid-template-columns: minmax(0, 1fr);
				overflow: hidden;
				border-radius: 12px;
				background: #ffffff;
			}
			.card img.mk-gn0ga6 {
				display: block;
				width: 100%;
				height: auto;
				aspect-ratio: 4 / 3;
				object-fit: cover;
			}
			.name.mk-gn0ga6 {
				padding: 8px 10px 10px;
				font-size: 15px;
				color: #212529;
			}
			.photo.mk-gn0ga6 {
				display: flex;
				align-items: center;
				gap: 12px;
				margin-top: 16px;
			}
			.thumb.mk-gn0ga6 {
				width: 72px;
				min-width: 72px;
				height: 72px;
				border: 2px solid #264653;
				border-radius: 16px;
				object-fit: contain;
				object-position: 0% 100%;
			}
			.status.mk-gn0ga6 {
				font-size: 15px;
				color: #495057;
			}
			.action.mk-gn0ga6 {
				display: block;
				width: 100%;
				margin-top: 12px;
				padding: 10px 16px;
				border: 2px solid #264653;
				border-radius: 10px;
				background: #ffffff;
				color: #264653;
				font-family: inherit;
				font-size: 17px;
				text-align: left;
			}
